{
  "name": "magpie-comfyui-link",
  "version": "0.2.0",
  "license": "MIT",
  "description": "Expose ComfyUI resources, native API workflow submission and image results to agents through Magpie.",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/321sssrt-bit/magpie-comfyui.git"
  },
  "homepage": "https://www.npmjs.com/package/magpie-comfyui-link",
  "type": "module",
  "main": "./index.js",
  "magpie": {
    "panels": [
      {
        "slot": "settings",
        "title": "ComfyUI connections",
        "titles": {
          "zh": "ComfyUI 连接"
        },
        "file": "ui/settings.html"
      }
    ],
    "icon": "data:image/png;base64,"
  },
  "keywords": [
    "magpie",
    "magpie-plugin",
    "opencode",
    "opencode-plugin",
    "comfyui"
  ],
  "scripts": {
    "test": "node --test index.test.js ui/settings.test.js"
  },
  "files": [
    "index.js",
    "ui/settings.html",
    "ui/settings.js",
    "ui/settings.css",
    "README.md",
    "README.en.md",
    "LICENSE",
    "assets/readme-hero.png",
    "assets/icon.png"
